<section class="panel"><div class="panel-head"><div><h2>Project team</h2><p>Assigned staff and client-visible roles</p></div><a href="<?= url('projects/'.$record['id'].'/edit') ?>">Manage team</a></div><div class="team-list"><?php foreach($related['members']??[] as $member):?><div><span class="avatar"><?= e(mb_substr($member['name'],0,1)) ?></span><span><strong><?= e($member['name']) ?></strong><small><?= e($member['role_name']) ?></small></span></div><?php endforeach;?><?php if(empty($related['members'])):?><div class="empty-inline">No team members assigned.</div><?php endif;?></div></section>
<section class="panel"><div class="panel-head"><div><h2>Milestones</h2><p>Project delivery checkpoints</p></div></div><div class="compact-list"><?php foreach($related['milestones']??[] as $milestone):?><div class="list-row"><span class="list-main"><strong><?= e($milestone['title']) ?></strong><small>Due <?= e(date('d M Y',strtotime($milestone['due_date']))) ?></small></span><span class="status-badge <?= status_class($milestone['status']) ?>"><?= e($milestone['status']) ?></span></div><?php endforeach;?></div><?php if(can('projects.edit')):?><form class="mini-form" method="post" action="<?= url('projects/'.$record['id'].'/milestones') ?>"><?= csrf_field() ?><input name="title" required placeholder="Milestone title"><div><input type="date" name="due_date" required><button class="button button-secondary button-sm">Add milestone</button></div></form><?php endif;?></section>
<section class="panel span-2"><div class="panel-head"><div><h2>Post project update</h2><p>Staff updates can be published to the client by authorised managers</p></div></div><form class="mini-form" method="post" action="<?= url('projects/'.$record['id'].'/updates') ?>"><?= csrf_field() ?><input name="title" required placeholder="Update title"><textarea name="details" required placeholder="Summarise completed work, decisions and next steps"></textarea><div><input type="number" name="progress" min="0" max="100" value="<?= (int)$record['progress'] ?>" aria-label="Progress percentage"><?php if(can('projects.edit')&&auth()['user_type']==='admin'):?><label class="check-label"><input type="checkbox" name="is_client_visible" value="1"> Share with client</label><?php endif;?><button class="button button-primary button-sm">Post update</button></div></form></section>
<section class="panel span-2"><div class="panel-head"><div><h2>Project files</h2><p>Internal files and explicitly client-shared documents</p></div></div><div class="document-list"><?php foreach($related['files']??[] as $file):?><a href="<?= url('project-files/'.$file['id']) ?>"><i class="fa-solid fa-file"></i><span><strong><?= e($file['title']) ?></strong><small><?= $file['is_client_visible']?'Client visible':'Internal' ?> · <?= e(date('d M Y',strtotime($file['created_at']))) ?></small></span><i class="fa-solid fa-download"></i></a><?php endforeach;?><?php if(empty($related['files'])):?><div class="empty-inline">No project files.</div><?php endif;?></div><form class="mini-form inline-form" method="post" enctype="multipart/form-data" action="<?= url('projects/'.$record['id'].'/files') ?>"><?= csrf_field() ?><input name="title" required maxlength="190" placeholder="File title"><input type="file" name="attachment" required accept=".jpg,.jpeg,.png,.webp,.pdf,.txt,.csv,.docx,.xlsx"><?php if(can('projects.edit')&&auth()['user_type']==='admin'):?><label class="check-label"><input type="checkbox" name="is_client_visible" value="1"> Share with client</label><?php endif;?><button class="button button-secondary button-sm">Upload securely</button></form></section>
